// Actor model simulation in Node.js using worker_threads as actors
// Each worker = one actor with private state + message-based communication

const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

if (isMainThread) {
  // Supervisor / orchestrator actor
  function spawnActor(script, initialState) {
    return new Promise((resolve) => {
      const actor = new Worker(__filename, { workerData: initialState });
      const mailbox = [];

      // Send message to actor's mailbox
      function send(msg) {
        actor.postMessage(msg);
      }

      actor.on('message', (reply) => {
        console.log(`[Actor ${initialState.id}] replied:`, reply);
        resolve(reply);
      });

      actor.on('error', (err) => {
        // Supervision: log crash and could restart
        console.error(`[Supervisor] Actor ${initialState.id} crashed:`, err.message);
        // In real Erlang/Akka: apply restart strategy here
      });

      return send;
    });
  }

  // Spawn two actors with isolated private state
  async function main() {
    // Actor 1: counter actor
    const actor1 = new Worker(__filename, { workerData: { id: 1, count: 0 } });
    const actor2 = new Worker(__filename, { workerData: { id: 2, count: 100 } });

    // Message passing — no shared memory
    actor1.postMessage({ type: 'INCREMENT', amount: 5 });
    actor1.postMessage({ type: 'INCREMENT', amount: 3 });
    actor2.postMessage({ type: 'DECREMENT', amount: 20 });
    actor2.postMessage({ type: 'GET' });

    actor1.on('message', msg => console.log('[Main] Actor1:', msg));
    actor2.on('message', msg => console.log('[Main] Actor2:', msg));

    setTimeout(() => { actor1.terminate(); actor2.terminate(); }, 200);
  }

  main();
} else {
  // Each worker is an actor — owns private state exclusively
  let state = { count: workerData.count }; // private, never shared

  parentPort.on('message', (msg) => {
    // Process one message at a time (sequential within actor)
    switch (msg.type) {
      case 'INCREMENT':
        state.count += msg.amount;
        break;
      case 'DECREMENT':
        state.count -= msg.amount;
        break;
      case 'GET':
        // Send reply message (never expose state reference directly)
        parentPort.postMessage({ id: workerData.id, count: state.count });
        break;
    }
  });
}

// Message passing vs shared memory — conceptual comparison

// ---- SHARED MEMORY approach (requires explicit locking) ----
