// Thread A and Thread B both do: view[0]++
// Without Atomics.add(), this is a DATA RACE:
//   Thread A reads 0, Thread B reads 0,
//   Thread A writes 1, Thread B writes 1 — result is 1, not 2!

// ---- MESSAGE PASSING approach (no locking needed) ----
// Actor owns its counter privately:
function createCounterActor() {
  let count = 0; // PRIVATE state — no other actor touches this

  return function handleMessage(msg) {
    // Sequential processing — no concurrent access possible
    if (msg.type === 'increment') count += msg.by;
    if (msg.type === 'decrement') count -= msg.by;
    if (msg.type === 'get') return count;
    // State is safe because only THIS function ever reads/writes `count`
  };
}

// Location transparency: same API whether local or remote
const counter = createCounterActor();
counter({ type: 'increment', by: 5 });
counter({ type: 'increment', by: 3 });
console.log(counter({ type: 'get' })); // always 8 — no race possible
